-- World countries + states. Cities stay out of Postgres (too large); Nigeria LGAs remain in NigeriaLgaRef.
CREATE TABLE "CountryRef" (
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "emoji" TEXT,
    "catalogDir" TEXT,
    CONSTRAINT "CountryRef_pkey" PRIMARY KEY ("code")
);

CREATE TABLE "CountryStateRef" (
    "id" TEXT NOT NULL,
    "countryCode" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "type" TEXT,
    "catalogDir" TEXT,
    CONSTRAINT "CountryStateRef_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "CountryRef_name_idx" ON "CountryRef"("name");
CREATE UNIQUE INDEX "CountryStateRef_countryCode_code_key" ON "CountryStateRef"("countryCode", "code");
CREATE INDEX "CountryStateRef_countryCode_idx" ON "CountryStateRef"("countryCode");
CREATE INDEX "CountryStateRef_name_idx" ON "CountryStateRef"("name");

ALTER TABLE "CountryStateRef" ADD CONSTRAINT "CountryStateRef_countryCode_fkey" FOREIGN KEY ("countryCode") REFERENCES "CountryRef"("code") ON DELETE CASCADE ON UPDATE CASCADE;

